<?php
require __DIR__.'/includes/bootstrap.php';require_admin();require __DIR__.'/includes/layout.php';$days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='schedule'){$dentist=(int)($_POST['dentist_id']??0);$day=(int)($_POST['day_of_week']??-1);$start=post_string('start_time',5);$end=post_string('end_time',5);$slot=(int)($_POST['slot_minutes']??30);$errors=[];if(!$dentist||$day<0||$day>6||!valid_time($start)||!valid_time($end)||$start>=$end||$slot<5)$errors[]='Enter a valid dentist, day and time range.';if(!$errors){$q=$pdo->prepare('SELECT COUNT(*) FROM dentist_schedules WHERE dentist_id=? AND day_of_week=? AND is_active=1 AND start_time<? AND end_time>?');$q->execute([$dentist,$day,$end,$start]);if($q->fetchColumn())$errors[]='This schedule overlaps an existing schedule for that dentist.';}if(!$errors){$q=$pdo->prepare('INSERT INTO dentist_schedules(dentist_id,day_of_week,start_time,end_time,slot_minutes) VALUES(?,?,?,?,?)');$q->execute([$dentist,$day,$start,$end,$slot]);audit($pdo,'schedule.created','dentist',$dentist);flash('success','Availability schedule added.');redirect('schedules.php');}}
 if($action==='block'){$dentist=(int)($_POST['dentist_id']??0);$date=post_string('unavailable_date',10);$start=post_string('start_time',5);$end=post_string('end_time',5);$reason=post_string('reason',255);$errors=[];if(!valid_date($date)||(($start!==''||$end!=='')&&(!valid_time($start)||!valid_time($end)||$start>=$end)))$errors[]='Enter a valid date and optional time range.';if(!$errors){$q=$pdo->prepare('INSERT INTO unavailable_slots(dentist_id,unavailable_date,start_time,end_time,reason) VALUES(?,?,?,?,?)');$q->execute([$dentist?:null,$date,$start?:null,$end?:null,$reason?:null]);audit($pdo,'schedule.blocked','dentist',$dentist?:null);flash('success','Unavailable time recorded.');redirect('schedules.php');}}
 if($action==='delete_schedule'){$id=(int)$_POST['id'];$pdo->prepare('DELETE FROM dentist_schedules WHERE id=?')->execute([$id]);flash('success','Schedule removed.');redirect('schedules.php');}if($action==='delete_block'){$id=(int)$_POST['id'];$pdo->prepare('DELETE FROM unavailable_slots WHERE id=?')->execute([$id]);flash('success','Blocked time removed.');redirect('schedules.php');}}
$dentists=$pdo->query("SELECT id,CONCAT(first_name,' ',last_name) name FROM dentists WHERE is_active=1 ORDER BY last_name")->fetchAll();$schedules=$pdo->query("SELECT s.*,CONCAT(d.first_name,' ',d.last_name) dentist FROM dentist_schedules s JOIN dentists d ON d.id=s.dentist_id ORDER BY d.last_name,s.day_of_week,s.start_time")->fetchAll();$blocks=$pdo->query("SELECT u.*,CONCAT(d.first_name,' ',d.last_name) dentist FROM unavailable_slots u LEFT JOIN dentists d ON d.id=u.dentist_id WHERE u.unavailable_date>=CURDATE() ORDER BY u.unavailable_date,u.start_time")->fetchAll();page_header('Schedules & Availability','schedules');
?><?php if(!empty($errors)):?><div class="alert error"><?=e(implode(' ',$errors))?></div><?php endif?><div class="grid panels"><section class="card"><h2>Weekly dentist schedules</h2><div class="table-wrap"><table><thead><tr><th>Dentist</th><th>Day</th><th>Hours</th><th>Slot</th><th></th></tr></thead><tbody><?php foreach($schedules as $s):?><tr><td>Dr. <?=e($s['dentist'])?></td><td><?=$days[$s['day_of_week']]?></td><td><?=date('g:i A',strtotime($s['start_time']))?>–<?=date('g:i A',strtotime($s['end_time']))?></td><td><?=$s['slot_minutes']?> min</td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="delete_schedule"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="btn danger sm" data-confirm="Remove this schedule?">Remove</button></form></td></tr><?php endforeach?><?php if(!$schedules):?><tr><td colspan="5" class="empty">No weekly schedules yet.</td></tr><?php endif?></tbody></table></div><h2 style="margin-top:25px">Add weekly availability</h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="schedule"><label>Dentist<select name="dentist_id" required><?php foreach($dentists as $d):?><option value="<?=$d['id']?>">Dr. <?=e($d['name'])?></option><?php endforeach?></select></label><label>Day<select name="day_of_week"><?php foreach($days as $i=>$day):?><option value="<?=$i?>"><?=$day?></option><?php endforeach?></select></label><label>Starts<input type="time" name="start_time" required></label><label>Ends<input type="time" name="end_time" required></label><label>Slot minutes<input type="number" name="slot_minutes" min="5" step="5" value="30" required></label><div class="full"><button>Add schedule</button></div></form></section><section class="card"><h2>Blocked dates & times</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Who / Reason</th><th></th></tr></thead><tbody><?php foreach($blocks as $b):?><tr><td><?=date('M j, Y',strtotime($b['unavailable_date']))?><br><small><?=$b['start_time']?date('g:i A',strtotime($b['start_time'])).'–'.date('g:i A',strtotime($b['end_time'])):'All day'?></small></td><td><?=e($b['dentist']?'Dr. '.$b['dentist']:'Entire clinic')?><br><small><?=e($b['reason'])?></small></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="delete_block"><input type="hidden" name="id" value="<?=$b['id']?>"><button class="btn danger sm">Remove</button></form></td></tr><?php endforeach?><?php if(!$blocks):?><tr><td colspan="3" class="empty">No upcoming blocked times.</td></tr><?php endif?></tbody></table></div><h2 style="margin-top:25px">Block availability</h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="block"><label class="full">Dentist<select name="dentist_id"><option value="">Entire clinic</option><?php foreach($dentists as $d):?><option value="<?=$d['id']?>">Dr. <?=e($d['name'])?></option><?php endforeach?></select></label><label>Date<input type="date" name="unavailable_date" min="<?=date('Y-m-d')?>" required></label><label>Reason<input name="reason" maxlength="255"></label><label>From (optional)<input type="time" name="start_time"></label><label>To (optional)<input type="time" name="end_time"></label><div class="full"><button>Block time</button></div></form></section></div><?php page_footer();
